'use strict';
const technicalView=switchView;
function showAudience(route,changeHash=true){const tech=route==='technical';document.body.classList.toggle('audience-public',!tech);$('audienceWelcome').hidden=route!=='home';$('publicMission').hidden=route!=='mission';if(changeHash&&location.hash!=='#'+(tech?'overview':route))location.hash=tech?'overview':route;window.scrollTo({top:0,behavior:'instant'});if($('felicetteFloating'))$('felicetteFloating').hidden=route!=='mission';if(route==='mission')renderMission();}
switchView=function(v){if(v==='home'||v==='mission'){showAudience(v,false);return;}if(titles[v]){showAudience('technical',false);technicalView(v);}};
$('enterPublic').onclick=()=>showAudience('mission');$('enterTechnical').onclick=()=>switchView('overview');$('chooseAudience').onclick=()=>showAudience('home');
const missionDefaults={step:0,goal:'explore',site:0,date:'2025-01-15T12:00',capacity:480,load:8,tracking:true,height:5,store:true,previewHour:0};let mission={...missionDefaults},countdownTimer=null;
const missionSteps=['Tu misión','El lugar','La fecha','La energía','La conexión','Tu plan','Resultado'];
const facts={
 terrain:{title:'¿Verde significa que ya podemos alunizar?',text:'Verde significa que la pendiente cumple el límite elegido a la escala del mapa. La altitud es otra variable. Para elegir un área de alunizaje hay que estudiar también rocas, rugosidad, incertidumbre, iluminación y comunicaciones con datos de alta resolución.',url:'https://pgda.gsfc.nasa.gov/products/78'},
 sunlight:{title:'El Sol puede estar arriba… y una montaña taparlo.',text:'La elevación dice qué tan alto está el Sol. El horizonte local agrega las montañas que lo rodean. En el polo sur el Sol pasa muy bajo: cambiar de sitio o de fecha puede cambiar las horas de luz.',url:'https://science.nasa.gov/solar-system/moon/phenomena-nasa-astronauts-will-encounter-at-moons-south-pole/'},
 night:{title:'La noche lunar no tiene una duración única en el polo.',text:'Un ciclo de amanecer a amanecer dura unos 29,5 días terrestres. Lejos de los polos, día y noche duran aproximadamente la mitad. En el polo sur, el relieve produce sombras de duración muy variable; hay regiones permanentemente en sombra.',url:'https://science.nasa.gov/resource/shadows-near-the-moons-south-pole/'},
 battery:{title:'La batería guarda energía; no crea energía.',text:'Una batería utilizable de 120 Wh, con un consumo constante de 8 W, ofrece 15 horas ideales sin recarga. El frío, la electrónica y otros consumos cambian el resultado real. En el juego mostramos un balance simplificado, no una batería de vuelo.',url:'https://www.nasa.gov/reference/moonbase-environment/'},
 orientation:{title:'El panel también tiene que mirar al Sol.',text:'El azimut indica hacia dónde gira el panel. Su inclinación indica cuánto se levanta desde la horizontal. En nuestro modelo, el seguimiento orienta el panel de frente al Sol cuando está visible. La eficiencia eléctrica y las pérdidas se aplican por separado.',url:'#energy'},
 cold:{title:'Tener batería no significa estar protegido del frío.',text:'La Luna tiene una atmósfera extremadamente tenue. La luz y la sombra producen condiciones térmicas muy distintas. El rover necesita protección y control térmico además de energía eléctrica. Este prototipo no calcula su temperatura.',url:'https://science.nasa.gov/moon/weather-on-the-moon/'},
 earth:{title:'La Tierra necesita un camino despejado.',text:'Una montaña puede bloquear la dirección hacia la Tierra. Una batería más grande no elimina ese obstáculo. Elevar una antena puede ayudar en algunos sitios; un enlace real también requiere potencia, antenas y una estación disponible.',url:'https://www.nasa.gov/glenn/glenn-expertise-space-exploration/scan/lunar-surface-propagation/'},
 storage:{title:'Podés guardar datos y enviarlos más tarde.',text:'Si la Tierra queda oculta, una memoria puede conservar los datos hasta la próxima ventana. Eso no mantiene comunicación en tiempo real. Un satélite repetidor sería otra arquitectura; no suponemos que exista un servicio disponible en este juego.',url:'https://www.nasa.gov/communicating-with-missions/delay-disruption-tolerant-networking/'},
 losses:{title:'En la Luna no hay lluvia que tape tus paneles.',text:'El rendimiento puede cambiar por orientación, temperatura, polvo, cables y conversión eléctrica. El porcentaje de pérdidas del laboratorio es un supuesto ajustable: no representa un pronóstico meteorológico ni una medición del sitio.',url:'https://science.nasa.gov/moon/lunar-atmosphere/'}
};
function factButton(key,label){return `<button class="did-you-know" data-fact="${key}">✦ ${label||'¿Sabías que…?'}</button>`;}
function showFact(key){const f=facts[key];if(!f)return;$('factTitle').textContent=f.title;$('factText').textContent=f.text;$('factSource').href=f.url;$('missionFact').showModal();}
$('closeFact').onclick=()=>$('missionFact').close();$('factSource').onclick=()=>{if($('factSource').getAttribute('href').startsWith('#'))$('missionFact').close();};
function missionIndex(date=mission.date){return Math.max(0,Math.min(lastPlanningIndex(),Math.round((new Date(date+'Z')-Date.UTC(2025,0,1))/3600000)));}
function missionAnalysis(site=mission.site,date=mission.date){if(!records.length)return null;const idx=missionIndex(date),samples=records.slice(idx,idx+168).map(r=>evaluate(sites[site],r,mission.height));const budget=solarBudget(samples,{capacityWh:mission.capacity,initialFraction:1,tracking:mission.tracking,azimuth:0,tilt:0,areaM2:.5,efficiency:.25,lossFraction:.15,irradiance:1361,stepHours:1,loadW:mission.load,chargeEfficiency:.9});return{idx,samples,light:visibleHours(samples,'sv'),earth:visibleHours(samples,'ev'),both:visibleHours(samples,'both'),dark:stats(samples,'sv').out,outage:stats(samples,'ev').out,budget};}
function choiceCard({label,description,selected,action,value,tag=''}){return `<button class="game-choice ${selected?'selected':''}" data-action="${action}" data-value="${value}" aria-pressed="${selected}">${tag?`<span class="choice-tag">${tag}</span>`:''}<strong>${label}</strong><span>${description}</span>${selected?'<i>✓ Elegido</i>':''}</button>`;}
function gameMetrics(a){return `<div class="game-metrics"><div><span>☼ Luz solar</span><b>${a.light} h</b><small>de las próximas 168 h</small></div><div><span>◎ Tierra visible</span><b>${a.earth} h</b><small>para un posible enlace directo</small></div><div><span>◒ Ambos visibles</span><b>${a.both} h</b><small>luz y comunicación a la vez</small></div></div>`;}
function gameHorizon(a){const t=mission.previewHour,c=a.samples[t];return `<div class="game-horizon"><div class="game-horizon-head"><b>Así se ve el cielo desde tu sitio</b><span>${hoursLabel(a.idx+t)}</span></div><svg viewBox="0 0 600 280" role="img" aria-label="Sol y Tierra sobre el horizonte local de tu misión">${horizonMarkup(sites[mission.site],mission.height,c)}</svg><div class="game-sky-status"><button data-fact="sunlight" class="${c.sv?'available':''}">☼ Sol ${c.sv?'visible':'oculto'} · tocar para aprender</button><button data-fact="earth" class="${c.ev?'available':''}">◎ Tierra ${c.ev?'visible':'oculta'} · tocar para aprender</button></div><label>Mové el tiempo<input id="gameTime" type="range" min="0" max="167" step="1" value="${t}"></label><p class="game-small">La curva usa montañas reales dentro del radio analizado. Las posiciones del Sol y la Tierra son aproximadas. Amarillo discontinuo: horizonte a la altura del panel; relleno: horizonte de la antena.</p></div>`;}
function gameTimeline(a){return `<div class="game-window-tracks">${[['Luz solar','sv','#fbbf24'],['Tierra visible','ev','#22d3ee']].map(([label,key,col])=>`<div><span>${label}</span><div>${a.samples.map((s,i)=>`<i title="${hoursLabel(a.idx+i)}" style="background:${s[key]?col:'#243147'}"></i>`).join('')}</div></div>`).join('')}<p class="game-small">Siete días · cada bloque es una hora · UTC</p></div>`;}
function stageHeading(kicker,title,text){return `<div class="stage-heading"><span class="eyebrow">${kicker}</span><h1 tabindex="-1" id="gameStageTitle">${title}</h1><p>${text}</p></div>`;}

function mascotGuide(step){const guidance=[
 ['green','¡Hola! Soy Félicette.','Voy a acompañarte. Elegí qué te gustaría lograr con tu rover y descubramos qué necesita.','terrain'],
 ['terrain','Primero, miremos el suelo.','¿Altura o inclinación? Son distintas. Explorá la Luna en colores: el verde de pendientes indica menor inclinación a esa escala.','terrain'],
 ['terrain','El lugar cambia con el tiempo.','Probá otra fecha y observá el Sol y la Tierra: una buena semana puede ser muy distinta de la siguiente.','night'],
 ['energy','Hagamos que alcance la energía.','Compará un panel fijo con uno que sigue al Sol. Después elegí batería para las horas sin generación.','orientation'],
 ['comms','¿La Tierra puede vernos?','Busquemos un camino despejado. Si hay un corte, podés guardar datos; eso no mantiene el contacto en tiempo real.','earth'],
 ['terrain','Revisemos tus decisiones.','Si aparece una advertencia, volvé un paso y probá otra combinación. Aprender también es comparar.','cold'],
 ['green','¡Ya tenés tu primer plan!','Guardá tus elecciones o abrí el laboratorio para seguir investigando. Todavía hay que validar terreno, radio y temperatura.','cold']
 ][step];return `<aside class="felicette-guide"><img src="assets/felicette-${guidance[0]}.png" alt="Félicette, gata alienígena verde y blanca, tu guía de misión"><div><span class="eyebrow">FÉLICETTE · TU COPILOTA</span><h2>${guidance[1]}</h2><p>${guidance[2]}</p><button class="did-you-know" data-fact="${guidance[3]}">Dame una pista, Félicette ✦</button></div></aside>`;}

function renderMission(){const a=missionAnalysis();renderJourney();document.querySelector('.game-navigation').hidden=!journeyStarted;if(!journeyStarted){$('gameContent').innerHTML='';updateFloatingGuide();return;}let html='';
if(mission.step===0){html=stageHeading('COMANDANTE, TE NECESITAMOS','¿Tu primera misión lunar?','Vas a elegir dónde y cuándo alunizar, cómo conseguir energía y cuándo enviar noticias a casa. ¿Qué te gustaría priorizar?')+`<div class="game-choice-grid">${choiceCard({label:'Explorar con energía solar',description:'Buscá más oportunidades de luz para operar tu rover.',selected:mission.goal==='explore',action:'goal',value:'explore',tag:'☼ EXPLORAR'})}${choiceCard({label:'Enviar noticias a la Tierra',description:'Buscá ventanas para compartir tus fotos y descubrimientos.',selected:mission.goal==='connect',action:'goal',value:'connect',tag:'◎ CONECTAR'})}</div><div class="game-guide"><span>✦</span><p>No existe una misión ideal para todo. Vas a descubrir qué combinación se adapta mejor a tu objetivo.</p></div><p class="game-small">Planificamos un rover robótico durante siete días. No simulamos vuelos tripulados ni el lanzamiento de un cohete.</p>`;}
else if(!a){html=stageHeading('PREPARANDO EL CENTRO DE MISIÓN','Cargando el archivo NASA…','Esperá a que estén disponibles las posiciones del Sol y de la Tierra.');}
else if(mission.step===1){html=stageHeading('PASO 1 · EL LUGAR','¿Dónde querés alunizar?','Compará tres ubicaciones del terreno real de Site01. Un lugar puede ofrecer mucha luz y otro más tiempo de comunicación.')+`<div class="game-choice-grid three">${sites.map((s,i)=>{const x=missionAnalysis(i);return choiceCard({label:s.name,description:`☼ ${x.light} h de luz · ◎ ${x.earth} h de Tierra visible en siete días.`,selected:mission.site===i,action:'site',value:i,tag:'SITIO '+String.fromCharCode(65+i)});}).join('')}</div>`+''+factButton('terrain','¿Qué significa el verde?')+gameHorizon(a)+factButton('sunlight','¿Por qué una montaña cambia la misión?');}
else if(mission.step===2){const next=Math.min(lastPlanningIndex(),missionIndex()+168),alt=new Date(Date.UTC(2025,0,1,next)).toISOString().slice(0,16),b=missionAnalysis(mission.site,alt);html=stageHeading('PASO 2 · EL MOMENTO','¿Y si viajamos otra semana?','El mismo sitio puede cambiar con la fecha. Compará tu momento elegido con siete días después.')+`<div class="game-date-editor"><div><span class="eyebrow">CALENDARIO CONECTADO A NASA</span><h2>Elegí una fecha y confirmala.</h2><p>Datos horarios de 2025 y 2026. Evaluamos los siguientes siete días completos.</p></div><label>Día de inicio · UTC<input id="gameCalendar" type="date" min="2025-01-01" max="2026-12-24" value="${mission.date.slice(0,10)}"></label><label>Hora UTC<select id="gameHour">${Array.from({length:24},(_,h)=>`<option value="${String(h).padStart(2,'0')}" ${h===+mission.date.slice(11,13)?'selected':''}>${String(h).padStart(2,'0')}:00 UTC</option>`).join('')}</select></label><button id="applyGameDate" class="primary">Evaluar esta fecha →</button><p id="gameDateStatus" role="status">Fecha aplicada: ${hoursLabel(a.idx)}. Cambiar el calendario no aplica la fecha hasta tocar el botón.</p><div class="date-shortcuts"><button data-shift-date="-7">← 7 días</button><button data-shift-date="7">+ 7 días →</button><button data-set-date="2026-11-14T12:00">Probar 14 nov 2026</button></div></div><div class="game-choice-grid"><article class="game-date-card"><span>FECHA ELEGIDA</span><h2>${hoursLabel(a.idx)}</h2>${gameMetrics(a)}</article>${missionIndex()+168>lastPlanningIndex()?'<article class="game-date-card"><span>FIN DE COBERTURA</span><h2>La semana siguiente sale del archivo.</h2><p>Tu fecha elegida sí tiene siete días completos. Para comparar otra semana, retrocedé la fecha; no reemplazamos tu selección por otra fecha.</p></article>':`<article class="game-date-card"><span>SIETE DÍAS DESPUÉS</span><h2>${hoursLabel(next)}</h2>${gameMetrics(b)}<button data-action="date" data-value="${alt}">Elegir esta fecha →</button></article>`}</div>`+factButton('night','¿Cuánto dura el día lunar?')+gameHorizon(a);}
else if(mission.step===3){html=stageHeading('PASO 3 · LA ENERGÍA','Que no se apague tu aventura.','Elegí la capacidad de batería y cómo orientar el panel. Mirá cómo cambia la energía disponible.')+`<div class="game-choice-grid three">${[120,480,1440].map(cap=>choiceCard({label:cap+' Wh',description:'Autonomía sin recarga: '+(cap/mission.load).toFixed(0)+' h ideales.',selected:mission.capacity===cap,action:'capacity',value:cap,tag:'BATERÍA UTILIZABLE'})).join('')}</div><div class="game-choice-grid">${choiceCard({label:'Panel horizontal fijo',description:'Es simple, pero puede aprovechar poco un Sol muy bajo.',selected:!mission.tracking,action:'tracking',value:'false',tag:'ORIENTACIÓN'})}${choiceCard({label:'Panel que sigue al Sol',description:'El modelo orienta el panel de frente cuando el Sol es visible.',selected:mission.tracking,action:'tracking',value:'true',tag:'SEGUIMIENTO IDEAL'})}</div><div class="game-metrics"><div><span>Generación estimada</span><b>${Math.round(a.budget.generatedWh)} Wh</b><small>en siete días</small></div><div><span>Batería al final</span><b>${Math.round(a.budget.finalStoredWh)} Wh</b><small>de ${mission.capacity} Wh utilizables</small></div><div><span>Energía que faltaría</span><b>${Math.round(a.budget.unservedWh)} Wh</b><small>${a.budget.unservedWh<.01?'El balance horario cubre el consumo.':'Conviene revisar la configuración.'}</small></div></div>${gameEnergyFlow(a)}<p class="game-small">Supuestos de juego: panel 0,5 m², eficiencia 25 %, pérdidas 15 %, carga 90 %, consumo 8 W, batería inicialmente llena. Sin modelo térmico.</p><div class="game-facts-row">${factButton('battery','¿Cuánto dura mi batería?')}${factButton('orientation','¿Cómo se orienta el panel?')}${factButton('cold','¿Y el frío?')}</div>`;}
else if(mission.step===4){html=stageHeading('PASO 4 · LA CONEXIÓN','¿Cómo enviamos noticias a casa?','Una antena más alta puede despejar obstáculos. Si la Tierra queda oculta, podés guardar los datos para enviarlos después.')+`<div class="game-choice-grid three">${[1,5,20].map(h=>choiceCard({label:h+' m',description:'Altura de la antena sobre el terreno real.',selected:mission.height===h,action:'height',value:h,tag:'ANTENA / OBSERVACIÓN'})).join('')}</div><div class="game-choice-grid">${choiceCard({label:'Necesito contacto en tiempo real',description:'Los cortes de visibilidad son un riesgo para este objetivo.',selected:!mission.store,action:'store',value:'false'})}${choiceCard({label:'Guardar y enviar después',description:'Puedo aceptar cortes; los datos esperan hasta el próximo contacto.',selected:mission.store,action:'store',value:'true'})}</div>`+gameMetrics(a)+`<div class="game-guide"><span>◎</span><p>El mayor corte del período es de <b>${a.outage} h</b>. ${mission.store?'Guardar datos ayuda a atravesarlo, pero no crea comunicación continua.':'Tu plan necesita revisar cómo operar durante ese corte.'}</p></div>`+gameHorizon(a)+factButton('storage','¿Qué hace un satélite repetidor?');}
else{const issues=[];if(a.budget.unservedWh>.01)issues.push('El balance indica energía insuficiente en algunas horas.');if(a.outage>0&&!mission.store)issues.push('Hay cortes de visibilidad y pediste contacto en tiempo real.');if(a.outage===168)issues.push('No hay contacto directo en el período: guardar datos no permite enviarlos dentro de estos siete días.');html=stageHeading(mission.step===6?'MISIÓN SIMULADA · APRENDIZAJE COMPLETADO':'PASO 5 · LA REVISIÓN',mission.step===6?'Tu misión tiene un plan.':'Cada decisión cuenta.',mission.step===6?'Descubriste cómo lugar, fecha, energía y horizonte se relacionan. Podés cambiar tus elecciones y volver a comparar.':'Revisá tu configuración antes de la cuenta regresiva. Las advertencias forman parte del aprendizaje.')+`<div class="game-plan-header"><div><span>SITIO</span><b>${sites[mission.site].name}</b></div><div><span>FECHA UTC</span><b>${hoursLabel(a.idx)}</b></div><div><span>PRIORIDAD</span><b>${mission.goal==='explore'?'Explorar con luz solar':'Conectar con la Tierra'}</b></div></div>`+gameMetrics(a)+gameTimeline(a)+`<div class="game-checklist"><h2>${issues.length?'Tu plan tiene aspectos para revisar':'El balance simplificado cubre las decisiones elegidas'}</h2>${issues.map(x=>`<p class="game-warning">△ ${x}</p>`).join('')}<p>✓ Comparaste lugares y fechas.</p><p>✓ Exploraste el Sol y la Tierra sobre el horizonte.</p><p>✓ Elegiste batería, orientación y estrategia de datos.</p><p class="game-small">Falta validar incertidumbre del terreno, relieve lejano, enlace de radio y supervivencia térmica. Completar el juego no certifica la viabilidad de una misión.</p></div><div class="game-facts-row"><button id="gameToTechnical">Ver mi escenario en el laboratorio ↗</button><button id="downloadMission">↓ Descargar mi plan</button>${factButton('cold','¿Qué falta para una misión real?')}</div>`;}
if(missionFeedback)html=html.replace('</div>', '</div>'+decisionFeedbackMarkup());$('gameContent').innerHTML=html;mountTerrainExplorers();updateFloatingGuide();$('gameBack').disabled=mission.step===0;$('gameNext').disabled=!records.length;$('gameNext').hidden=mission.step===6;$('gameNext').textContent=mission.step===0?'Listos… ¡a planificar! →':mission.step===5?'3, 2, 1… simular misión 🚀':'Continuar →';$('gameStepLabel').textContent=mission.step===6?'Aprendiste a planificar':'Decisión '+(mission.step+1)+' de 6';bindGameControls();}
function bindGameControls(){document.querySelectorAll('#gameContent [data-action]').forEach(b=>b.onclick=()=>{const before=missionAnalysis(),key=b.dataset.action,value=b.dataset.value;mission[key]=['site','capacity','height'].includes(key)?+value:['tracking','store'].includes(key)?value==='true':value;mission.previewHour=0;guideTipIndex=0;missionFeedback=assessDecision(key,before,missionAnalysis());renderMission();});document.querySelectorAll('#gameContent [data-fact]').forEach(b=>b.onclick=()=>showFact(b.dataset.fact));if($('applyGameDate')){$('applyGameDate').onclick=applyMissionDate;for(const id of ['gameCalendar','gameHour'])$(id).oninput=()=>{$('gameDateStatus').textContent='Fecha sin aplicar. Tocá «Evaluar esta fecha» para recalcular el escenario.';$('gameNext').disabled=true;};}if($('gameTime'))$('gameTime').oninput=e=>{mission.previewHour=+e.target.value;const a=missionAnalysis(),c=a.samples[mission.previewHour],box=document.querySelector('.game-horizon');box.querySelector('svg').innerHTML=horizonMarkup(sites[mission.site],mission.height,c);box.querySelector('.game-horizon-head span').textContent=hoursLabel(a.idx+mission.previewHour);box.querySelector('[data-fact=sunlight]').textContent='☼ Sol '+(c.sv?'visible':'oculto')+' · tocar para aprender';box.querySelector('[data-fact=earth]').textContent='◎ Tierra '+(c.ev?'visible':'oculta')+' · tocar para aprender';box.querySelector('[data-fact=sunlight]').classList.toggle('available',c.sv);box.querySelector('[data-fact=earth]').classList.toggle('available',c.ev);};if($('gameToTechnical'))$('gameToTechnical').onclick=()=>{$('site').value=mission.site;$('date').value=mission.date;$('height').value=mission.height;$('battery').value=mission.capacity;$('load').value=mission.load;$('solarTracking').value=mission.tracking?'tracking':'fixed';$('panelAzimuth').value=0;$('panelTilt').value=0;$('solarTracking').dispatchEvent(new Event('input',{bubbles:true}));resetScrubber();update();switchView('overview');};document.querySelectorAll('[data-shift-date]').forEach(b=>b.onclick=()=>{const idx=missionIndex()+Number(b.dataset.shiftDate)*24;applyDateValue(new Date(Date.UTC(2025,0,1,idx)).toISOString().slice(0,16));});document.querySelectorAll('[data-set-date]').forEach(b=>b.onclick=()=>applyDateValue(b.dataset.setDate));if($('downloadMission'))$('downloadMission').onclick=()=>{const a=missionAnalysis();download('mi-mision-lunar.json',JSON.stringify({educational:true,choices:mission,site:sites[mission.site],sunlightHours:a.light,earthVisibilityHours:a.earth,longestDarkHours:a.dark,longestEarthOutageHours:a.outage,energy:{generatedWh:a.budget.generatedWh,finalBatteryWh:a.budget.finalStoredWh,unservedWh:a.budget.unservedWh},sources:['NASA SVS 5415 (2025)','NASA SVS 5587 (2026)'],limitations:['LOLA Site01 sampled horizon, limited radius and resolution','Simplified solar and battery model','No thermal or launch model','No operational validation']},null,2),'application/json');};}
function missionCountdown(next){if(countdownTimer)return;let n=3;$('missionCountdown').hidden=false;$('countdownCaption').textContent=next===1?'¡Empieza tu preparación!':'¡Vamos a la Luna… en la simulación!';$('countdownNumber').textContent=n;countdownTimer=setInterval(()=>{n--;if(n>0){$('countdownNumber').textContent=n;return;}clearInterval(countdownTimer);countdownTimer=null;$('missionCountdown').hidden=true;mission.step=next;missionFeedback=null;renderMission();window.scrollTo({top:0,behavior:'instant'});$('gameStageTitle')?.focus({preventScroll:true});},650);}
$('gameNext').onclick=()=>{if(!records.length)return;if(mission.step===0)return missionCountdown(1);if(mission.step===5)return missionCountdown(6);mission.step++;missionFeedback=null;renderMission();window.scrollTo({top:0,behavior:'instant'});$('gameStageTitle')?.focus({preventScroll:true});};$('gameBack').onclick=()=>{mission.step=Math.max(0,mission.step-1);missionFeedback=null;renderMission();window.scrollTo({top:0,behavior:'instant'});};$('restartMission').onclick=()=>{journeyStarted=false;guideClosed=false;guideStep=-1;missionFeedback=null;mission={...missionDefaults};renderMission();window.scrollTo({top:0,behavior:'instant'});};window.addEventListener('lunar-data-ready',()=>{if(!$('publicMission').hidden)renderMission();});
const originalShare=$('shareLink').onclick;$('shareLink').onclick=async()=>{if(!document.body.classList.contains('audience-public'))return originalShare();try{await navigator.clipboard.writeText(location.origin+'/#mission');toast('Enlace de la misión guiada copiado.');}catch{toast('Compartí esta página con #mission al final.');}};
const initialRoute=location.hash.slice(1);if(titles[initialRoute])showAudience('technical',false);else showAudience(initialRoute==='mission'?'mission':'home',false);
